HEADERS = {
    'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36',
    'Referer': 'https://outward.wiki.gg/wiki/Outward_Wiki',
}

def download_image(args):
    url, folder = args
    try:
        filename = url.split('/')[-1]
        filename = re.sub(r'[^\w\-.]', '_', filename.replace('%27','_').replace('%20','_'))
        filepath = f'images/{folder}/{filename}'

        os.makedirs(f'images/{folder}', exist_ok=True)

        if os.path.exists(filepath):
            return (url, True, 'exists')

        response = requests.get(url, headers=HEADERS, timeout=10)
        if response.status_code == 200:
            with open(filepath, 'wb') as f:
                f.write(response.content)
            return (url, True, 'downloaded')
        else:
            return (url, False, f'status_{response.status_code}')
    except Exception as e:
        return (url, False, str(e)[:50])

def main():
    print(f'Downloading {len(IMAGES)} images...')

    downloaded = 0
    failed = 0
    failed_urls = []

    # Use 3 threads to avoid rate limiting
    with ThreadPoolExecutor(max_workers=3) as executor:
        futures = {executor.submit(download_image, img): img for img in IMAGES}

        for i, future in enumerate(as_completed(futures), 1):
            url, success, status = future.result()
            if success:
                downloaded += 1
            else:
                failed += 1
                failed_urls.append((url, status))

            if i % 50 == 0:
                print(f'Progress: {i}/{len(IMAGES)} ({downloaded} ok, {failed} failed)')

            # Small delay to avoid rate limiting
            time.sleep(0.2)

    print(f'\n✅ Downloaded: {downloaded}')
    print(f'❌ Failed: {failed}')

    if failed_urls:
        print(f'\nFailed URLs:')
        for url, status in failed_urls[:10]:
            print(f'  {status}: {url}')
        if len(failed_urls) > 10:
            print(f'  ... and {len(failed_urls) - 10} more')

    # Save failed URLs for retry
    if failed_urls:
        with open('failed_urls.txt', 'w') as f:
            for url, status in failed_urls:
                f.write(f'{url}\t{status}\n')
        print(f'\nFailed URLs saved to failed_urls.txt')

if __name__ == '__main__':
    main()
